<script setup>
import {computed,ref} from 'vue';import {simulateBoundaries} from '../sim/models/boundary.mjs';
const layout=ref('modular'),movePayment=ref(false),directDbWrite=ref(false),clientAuthOnly=ref(false);const r=computed(()=>simulateBoundaries({layout:layout.value,movePayment:movePayment.value,directDbWrite:directDbWrite.value,clientAuthOnly:clientAuthOnly.value}));
</script><template><section class="sim-lab"><div class="sim-controls"><div><span>部署方式</span><div class="sim-segment"><button :aria-pressed="layout==='modular'" @click="layout='modular'">單一 App／模組分責任</button><button :aria-pressed="layout==='services'" @click="layout='services'">多個 Services</button></div></div><div><span>改一條 boundary</span><div class="sim-segment"><button :aria-pressed="movePayment" @click="movePayment=!movePayment">Payment 獨立部署</button><button :aria-pressed="directDbWrite" @click="directDbWrite=!directDbWrite">Payment 直接寫 Order DB</button><button :aria-pressed="clientAuthOnly" @click="clientAuthOnly=!clientAuthOnly">只靠前端授權</button></div></div></div><div class="boundary-system"><div class="boundary-zone"><b>Order</b><span>建立／修改訂單</span></div><div class="boundary-zone"><b>Inventory</b><span>庫存規則</span></div><div :class="['boundary-zone',{'is-separated':r.paymentBoundary}]"><b>Payment</b><span>{{r.paymentBoundary?'跨 boundary':'同一 deployment unit'}}</span></div><div class="boundary-zone"><b>Shipping</b><span>出貨結果</span></div></div><div class="sim-metrics"><div><span>部署單位</span><strong>{{r.deployUnits}}</strong></div><div><span>跨界 calls</span><strong>{{r.crossBoundaryCalls}}</strong></div><div :class="{'is-bad':r.sharedWrites>0}"><span>共享直接寫入</span><strong>{{r.sharedWrites}}</strong></div><div :class="{'is-bad':r.trustCrossings>0&&clientAuthOnly}"><span>Trust crossings</span><strong>{{r.trustCrossings}}</strong></div></div><div class="sim-consequence"><strong>切 boundary 不是免費的</strong><p v-if="r.risks.length">{{r.risks.join('；')}}。</p><p v-else>目前責任仍可在單一 deployment unit 內清楚分開。只有出現獨立部署、擴展、安全或故障隔離需求時，才需要為跨服務成本付費。</p></div></section></template>